// VM is the shared utility library, loaded globally via _includes/head-scripts.html (js/**). This page uses VM.expressions.makeFunction, VM.expressions.makeNumber, VM.sampling.seededRandom, VM.sampling.gaussianRandom, VM.filters.movingAverageFilter, VM.filters.emaFilter, VM.filters.kalman1DFilter, VM.plotting.paddedRange, VM.ui.renderTable.
VM = window.VM
urlParams = new URLSearchParams(window.location.search)

tabSlugToLabel = new Map([
  ["signal", "Signal & Sampling"],
  ["filters", "Filter Parameters"]
])

tabLabelToSlug = new Map([
  ["Signal & Sampling", "signal"],
  ["Filter Parameters", "filters"]
])

methodOptions = ["Simple Moving Average", "Exponential Moving Average", "Kalman Filter"]

methodSlugToLabel = new Map([
  ["sma", "Simple Moving Average"],
  ["moving-average", "Simple Moving Average"],
  ["moving_average", "Simple Moving Average"],

  ["ema", "Exponential Moving Average"],
  ["low-pass", "Exponential Moving Average"],
  ["lowpass", "Exponential Moving Average"],
  ["exponential-moving-average", "Exponential Moving Average"],

  ["kalman", "Kalman Filter"],
  ["kalman-filter", "Kalman Filter"],
  ["kalman_filter", "Kalman Filter"]
])

methodLabelToSlug = new Map([
  ["Simple Moving Average", "sma"],
  ["Exponential Moving Average", "ema"],
  ["Kalman Filter", "kalman"]
])

initialMethods = {
  const raw = urlParams.get("show")
  if (raw === null || raw.trim() === "") return methodOptions

  const selected = raw
    .split(",")
    .map(s =&gt; s.trim().toLowerCase())
    .map(s =&gt; methodSlugToLabel.get(s))
    .filter(Boolean)

  return selected.length &gt; 0 ? Array.from(new Set(selected)) : methodOptions
}

initialMax = urlParams.get("max") ?? "60"

initialAlpha = {
  const raw = Number.parseFloat(urlParams.get("alpha"))
  return Number.isFinite(raw) ? Math.min(Math.max(raw, 0), 0.99) : 0.9
}

initialK = {
  const raw = Number.parseInt(urlParams.get("k"), 10)
  return Number.isFinite(raw) ? Math.max(1, raw) : 5
}

initialR = {
  const raw = Number.parseFloat(urlParams.get("R"))
  return Number.isFinite(raw) ? Math.min(Math.max(raw, 0.001), 2) : 0.16
}

initialQ = {
  const raw = Number.parseFloat(urlParams.get("Q"))
  return Number.isFinite(raw) ? Math.min(Math.max(raw, 0), 1) : 0.05
}
// Pressing Enter in the signal/noise/endpoint/seed fields clicks Plot
// instead of submitting the field's own (invisible) form. Depends only on
// the stable views, so this wiring runs once and is never re-attached.
enterToPlot = {
  for (const view of [viewof fText, viewof sigmaText, viewof bText, viewof seedText]) {
    const input = view.querySelector("input")
    if (!input) continue
    input.addEventListener("keydown", (e) =&gt; {
      if (e.key !== "Enter") return
      e.preventDefault()
      viewof plotTrigger.querySelector("button").click()
    })
  }
}
// Keeps the total sample count, filter parameters, and method choices
// shareable as these reactive controls change (independent of the Plot
// button).
urlSyncControls = {
  const params = new URLSearchParams(window.location.search)
  params.set("max", maxNInput)
  params.set("alpha", String(alpha))
  params.set("k", String(windowK))
  params.set("R", String(R))
  params.set("Q", String(Q))
  params.set("show", methods.map(m =&gt; methodLabelToSlug.get(m)).filter(Boolean).join(","))
  history.replaceState(null, "", `${window.location.pathname}?${params}`)
  return true
}
// Wires the ::: {.panel-tabset} above to a `tab` URL param, the same
// URL-shareable convention as every other control on this page: activates
// the URL-requested tab on load (via Bootstrap's Tab API, since Quarto's
// tabset is plain Bootstrap nav-tabs under the hood), and keeps the URL
// updated whenever the user switches tabs by hand. Matches tabs by their
// visible label text rather than Quarto's auto-generated element IDs
// (e.g. "tabset-1-1"), which aren't stable identifiers to build a URL
// contract on.
tabSync = {
  const bootstrap = window.bootstrap
  const links = Array.from(document.querySelectorAll(".panel-tabset .nav-link"))

  const initialLabel = tabSlugToLabel.get(urlParams.get("tab"))
  if (initialLabel) {
    const initialLink = links.find(link =&gt; link.textContent.trim() === initialLabel)
    if (initialLink) bootstrap.Tab.getOrCreateInstance(initialLink).show()
  }

  for (const link of links) {
    link.addEventListener("shown.bs.tab", () =&gt; {
      const slug = tabLabelToSlug.get(link.textContent.trim())
      if (!slug) return
      const params = new URLSearchParams(window.location.search)
      params.set("tab", slug)
      history.replaceState(null, "", `${window.location.pathname}?${params}`)
    })
  }

  return true
}
// committed snapshots fText/sigmaText/bText/seedText only when Plot is
// clicked, and writes everything back into the URL so the address bar
// stays a shareable link. It reads `viewof fText`/etc. (the stable DOM
// views) rather than `fText`/etc. (the reactive values), so it does NOT
// rerun on every keystroke — only when `plotTrigger` changes. It still
// runs once on initial page load, so the first render uses the
// URL-provided (or default) values with no click.
committed = {
  plotTrigger
  const math = window.math
  const fVal = (viewof fText).value
  const sigmaVal = (viewof sigmaText).value
  const bVal = (viewof bText).value
  const seedVal = (viewof seedText).value

  const sigmaNum = VM.expressions.makeNumber(math, sigmaVal)
  const bNum = VM.expressions.makeNumber(math, bVal)
  const seedNum = VM.expressions.makeNumber(math, seedVal)

  const params = new URLSearchParams(window.location.search)
  params.set("f", fVal)
  params.set("sigma", sigmaVal)
  params.set("b", bVal)
  params.set("seed", seedVal)
  params.set("max", maxNInput)
  params.set("alpha", String(alpha))
  params.set("k", String(windowK))
  params.set("R", String(R))
  params.set("Q", String(Q))
  params.set("show", methods.map(m =&gt; methodLabelToSlug.get(m)).filter(Boolean).join(","))
  history.replaceState(null, "", `${window.location.pathname}?${params}`)

  return {fText: fVal, sigma: sigmaNum, bEnd: bNum, seed: seedNum}
}
// result: for the current committed signal/noise/endpoint/seed and the
// live filter parameters (alpha, windowK, R, Q), draws maxN noisy
// measurements of f and runs all three filters over the entire stream.
//   rows — array of { i, x, trueVal, noisyVal, smaVal, emaVal, kalmanVal,
//     kalmanGain, smaErr, emaErr, kalmanErr }, one entry per sample
//     i = 0..maxN-1, x = i*b/(maxN-1).
//   f — parsed true signal, reused for the smooth reference curve in setup
result = {
  const math = window.math

  const f = VM.expressions.makeFunction(math, committed.fText)
  const fallback = x =&gt; NaN

  if (!f) return {rows: [], f: fallback}

  const sigma = committed.sigma
  const b = committed.bEnd
  const seed = committed.seed
  if (!Number.isFinite(sigma) || sigma &lt; 0 || !Number.isFinite(b) || b &lt;= 0 || !Number.isFinite(seed)) {
    return {rows: [], f}
  }

  const rng = VM.sampling.seededRandom(seed)
  const gaussian = VM.sampling.gaussianRandom(rng)

  const xs = []
  const trueVals = []
  const noisyVals = []
  for (let i = 0; i &lt; maxN; i++) {
    const x = i * b / (maxN - 1)
    const trueVal = f(x)
    const noisyVal = trueVal + sigma * gaussian()
    xs.push(x)
    trueVals.push(trueVal)
    noisyVals.push(noisyVal)
  }

  const smaVals = VM.filters.movingAverageFilter(noisyVals, windowK)
  const emaVals = VM.filters.emaFilter(noisyVals, alpha)
  const kalman = VM.filters.kalman1DFilter(noisyVals, {R, Q})

  const rows = []
  for (let i = 0; i &lt; maxN; i++) {
    rows.push({
      i, x: xs[i], trueVal: trueVals[i], noisyVal: noisyVals[i],
      smaVal: smaVals[i], emaVal: emaVals[i], kalmanVal: kalman.xs[i], kalmanGain: kalman.Ks[i],
      smaErr: Math.abs(smaVals[i] - trueVals[i]),
      emaErr: Math.abs(emaVals[i] - trueVals[i]),
      kalmanErr: Math.abs(kalman.xs[i] - trueVals[i])
    })
  }

  return {rows, f}
}
// setup computes the data needed by the main chart: a dense reference
// curve of the true signal over the entire committed domain, and axis
// ranges covering every sample.
setup = {
  if (result.rows.length === 0) {
    const empty = {lo: -3, hi: 3}
    return {refXs: [], refYs: [], xRange: empty, yRange: {lo: -1, hi: 1}}
  }

  const b = committed.bEnd
  const xRange = VM.plotting.paddedRange([0, b], {emptyRange: [-3, 3], relativePadding: 0.08, minPadding: 0.25})

  const sampleCount = 400
  const refXs = []
  const refYs = []
  for (let i = 0; i &lt; sampleCount; i++) {
    const x = b * i / (sampleCount - 1)
    refXs.push(x)
    refYs.push(result.f(x))
  }

  const yValues = []
  for (const y of refYs) if (Number.isFinite(y)) yValues.push(y)
  for (const row of result.rows) {
    if (Number.isFinite(row.noisyVal)) yValues.push(row.noisyVal)
    if (Number.isFinite(row.smaVal)) yValues.push(row.smaVal)
    if (Number.isFinite(row.emaVal)) yValues.push(row.emaVal)
    if (Number.isFinite(row.kalmanVal)) yValues.push(row.kalmanVal)
  }
  const yRange = VM.plotting.paddedRange(yValues, {emptyRange: [-1, 1], relativePadding: 0.15, minPadding: 0.5})

  return {refXs, refYs, xRange, yRange}
}
// mainPlot draws the true signal (over the full domain, as a fixed
// reference), every noisy measurement, and each enabled filter's estimate.
//
// _plotDiv is kept in a closure so Plotly reuses the same DOM node across
// reactive updates — this preserves zoom and pan when a parameter or
// checkbox changes.
mainPlot = {
  const Plotly = window.Plotly
  let _plotDiv = null

  return (rows, data, showSMA, showEMA, showKalman) =&gt; {
    const traces = [
      {x: data.refXs, y: data.refYs, type: "scatter", mode: "lines", name: "True signal", showlegend: true, line: {color: "#2563eb", width: 3}}
    ]

    const xs = []
    const noisyYs = []
    for (const row of rows) {
      xs.push(row.x)
      noisyYs.push(row.noisyVal)
    }
    traces.push({x: xs, y: noisyYs, type: "scatter", mode: "markers", name: "Noisy measurements", showlegend: true, marker: {color: "#9ca3af", size: 6, line: {color: "white", width: 0.5}}})

    if (showSMA && rows.length &gt; 0) {
      const ys = []
      for (const row of rows) ys.push(row.smaVal)
      traces.push({x: xs, y: ys, type: "scatter", mode: "lines", name: "Simple Moving Average", showlegend: true, line: {color: "#f59e0b", width: 2.5}})
    }
    if (showEMA && rows.length &gt; 0) {
      const ys = []
      for (const row of rows) ys.push(row.emaVal)
      traces.push({x: xs, y: ys, type: "scatter", mode: "lines", name: "Exponential Moving Average", showlegend: true, line: {color: "#16a34a", width: 2.5}})
    }
    if (showKalman && rows.length &gt; 0) {
      const ys = []
      for (const row of rows) ys.push(row.kalmanVal)
      traces.push({x: xs, y: ys, type: "scatter", mode: "lines+markers", name: "Kalman Filter", showlegend: true, line: {color: "#dc2626", width: 2.5}, marker: {color: "#dc2626", size: 5}})
    }

    const layout = {
      margin: {l: 0, r: 0, t: 0, b: 0},
      xaxis: {title: "x", range: [data.xRange.lo, data.xRange.hi], zeroline: true},
      yaxis: {title: "value", range: [data.yRange.lo, data.yRange.hi], zeroline: true},
      legend: {orientation: "h", y: -0.08},
      hovermode: "closest",
      uirevision: "static",  // keeps zoom/pan state across reactive updates
      autosize: true
    }
    const config = {responsive: true, displaylogo: false}

    // First render: create the div. Later renders: update in place (preserves zoom).
    if (!_plotDiv) {
      _plotDiv = document.createElement("div")
      _plotDiv.className = "plotly-box-large"
      Plotly.newPlot(_plotDiv, traces, layout, config)
      // newPlot fires before the div is in the DOM, so Plotly measures 0 width.
      // A ResizeObserver catches the real size once it's inserted and laid out,
      // and keeps correcting it on any later layout/viewport change.
      new ResizeObserver(() =&gt; Plotly.Plots.resize(_plotDiv)).observe(_plotDiv)
    } else {
      Plotly.react(_plotDiv, traces, layout, config)
    }
    return _plotDiv
  }
}
Each of these filters updates a running estimate from only the previous estimate and the newest measurement \(z_i\) — no stored history of the stream — which is what makes them run in O(1) memory and O(1) compute per sample. The simple moving average and exponential moving average (a.k.a. a first-order low-pass filter) both trade responsiveness for smoothness through a hand-picked constant (\(k\) or \(\alpha\)) that never changes:
\[
\text{SMA: } \hat x_i = \frac{1}{k}\sum_{j=i-k+1}^{i} z_j,
\qquad
\text{EMA: } \hat x_i = \alpha\, \hat x_{i-1} + (1-\alpha)\, z_i.
\]
The Kalman filter instead maintains a running estimate of its own uncertainty \(P_i\) and derives its gain from it at every step, given only two beliefs about the noise: \(R\), the assumed measurement-noise (sensor) variance, and \(Q\), the assumed process-noise variance (how much the true value is expected to drift between samples):
\[
P_i^- = P_{i-1} + Q,\qquad
K_i = \frac{P_i^-}{P_i^- + R},\qquad
\hat x_i = \hat x_{i-1} + K_i\,(z_i - \hat x_{i-1}),\qquad
P_i = (1-K_i)\,P_i^-,
\]
with no \(\alpha\) or \(k\) to tune by hand — open the convergence plots on the constant-signal example below to watch \(K_i\) shrink automatically as the filter grows more confident.

// VM is the shared utility library, loaded globally via _includes/head-scripts.html (js/**). This page uses VM.expressions.makeFunction2, VM.expressions.makeNumber, VM.plotting.paddedRange, VM.ui.renderTable, VM.numerical.rk4Solve.
VM = window.VM
tolerance = Math.pow(10, -tolExponent)
// Pressing Enter in the function/initial-condition/endpoint fields clicks
// Plot instead of submitting the field's own (invisible) form. Depends
// only on the stable views, so this wiring runs once and is never
// re-attached.
enterToPlot = {
  for (const view of [viewof fText, viewof y0, viewof bEnd]) {
    const input = view.querySelector("input")
    if (!input) continue
    input.addEventListener("keydown", (e) =&gt; {
      if (e.key !== "Enter") return
      e.preventDefault()
      viewof plotTrigger.querySelector("button").click()
    })
  }
}
// committed snapshots fText/y0/bEnd only when Plot is clicked, and writes
// them back into the URL so the address bar stays a shareable link. It
// reads `viewof fText`/`viewof y0`/`viewof bEnd` (the stable DOM views)
// rather than `fText`/`y0`/`bEnd` (the reactive values), so it does NOT
// rerun on every keystroke — only when `plotTrigger` changes. It still
// runs once on initial page load, so the first render uses the
// URL-provided (or default) values with no click.
committed = {
  plotTrigger
  const math = window.math
  const fVal = (viewof fText).value
  const y0Text = (viewof y0).value
  const bText = (viewof bEnd).value
  const y0Val = VM.expressions.makeNumber(math, y0Text)
  const bVal = VM.expressions.makeNumber(math, bText)

  const params = new URLSearchParams(window.location.search)
  params.set("f", fVal)
  params.set("y0", y0Text)
  params.set("b", bText)
  history.replaceState(null, "", `${window.location.pathname}?${params}`)

  return {fText: fVal, y0: y0Val, bEnd: bVal}
}
// rk45Solve(f, t0, y0, tEnd, tol, maxSteps) advances y' = f(t, y), y(t0) = y0
// from t0 to tEnd using the embedded Runge-Kutta-Fehlberg 4(5) pair,
// accepting a step only when its local error estimate is within tol and
// otherwise shrinking h and retrying. Returns:
//   ts, ys — the accepted trajectory, one entry per accepted step plus t0
//   steps — array of { t0, t1, h, dy, deriv }, one entry per accepted step:
//     deriv is f(t0, y) at the step's start, dy is the accepted increment
//   acceptedCount, rejectedCount — step counters
rk45Solve = (f, t0, y0, tEnd, tol, maxSteps) =&gt; {
  const c2 = 1 / 4, c3 = 3 / 8, c4 = 12 / 13, c5 = 1, c6 = 1 / 2
  const a21 = 1 / 4
  const a31 = 3 / 32, a32 = 9 / 32
  const a41 = 1932 / 2197, a42 = -7200 / 2197, a43 = 7296 / 2197
  const a51 = 439 / 216, a52 = -8, a53 = 3680 / 513, a54 = -845 / 4104
  const a61 = -8 / 27, a62 = 2, a63 = -3544 / 2565, a64 = 1859 / 4104, a65 = -11 / 40
  const b1 = 25 / 216, b3 = 1408 / 2565, b4 = 2197 / 4104, b5 = -1 / 5
  const b1s = 16 / 135, b3s = 6656 / 12825, b4s = 28561 / 56430, b5s = -9 / 50, b6s = 2 / 55

  const direction = tEnd &gt;= t0 ? 1 : -1
  const span = Math.abs(tEnd - t0)
  const hMin = span * 1e-10
  const hMax = span

  const ts = [t0]
  const ys = [y0]
  const steps = []
  let t = t0, y = y0
  let h = direction * span / 100
  let acceptedCount = 0
  let rejectedCount = 0

  // Safety valve: caps total solver attempts (accepted + rejected) so a
  // pathological (e.g. non-converging) right-hand side can't hang the
  // browser retrying rejected steps forever.
  const maxAttempts = maxSteps * 50
  let attempts = 0

  while (attempts &lt; maxAttempts) {
    if (direction &gt; 0 && t &gt;= tEnd - 1e-12) break
    if (direction &lt; 0 && t &lt;= tEnd + 1e-12) break
    if (acceptedCount &gt;= maxSteps) break
    attempts += 1

    if (direction &gt; 0 && t + h &gt; tEnd) h = tEnd - t
    if (direction &lt; 0 && t + h &lt; tEnd) h = tEnd - t

    const k1 = f(t, y)
    const k2 = f(t + c2 * h, y + h * (a21 * k1))
    const k3 = f(t + c3 * h, y + h * (a31 * k1 + a32 * k2))
    const k4 = f(t + c4 * h, y + h * (a41 * k1 + a42 * k2 + a43 * k3))
    const k5 = f(t + c5 * h, y + h * (a51 * k1 + a52 * k2 + a53 * k3 + a54 * k4))
    const k6 = f(t + c6 * h, y + h * (a61 * k1 + a62 * k2 + a63 * k3 + a64 * k4 + a65 * k5))

    const y4 = y + h * (b1 * k1 + b3 * k3 + b4 * k4 + b5 * k5)
    const y5 = y + h * (b1s * k1 + b3s * k3 + b4s * k4 + b5s * k5 + b6s * k6)

    const error = Math.abs(y5 - y4)

    let factor = 5
    if (error !== 0) {
      factor = 0.9 * Math.pow(tol / error, 0.2)
      if (factor &gt; 5) factor = 5
      if (factor &lt; 0.1) factor = 0.1
    }
    let hNew = h * factor
    if (Math.abs(hNew) &lt; hMin) hNew = direction * hMin
    if (Math.abs(hNew) &gt; hMax) hNew = direction * hMax

    if (!Number.isFinite(error) || error &lt;= tol || Math.abs(h) &lt;= hMin) {
      const tNext = t + h
      steps.push({t0: t, t1: tNext, h, dy: y5 - y, deriv: k1})
      t = tNext
      y = y5
      ts.push(t)
      ys.push(y)
      acceptedCount += 1
      h = hNew
    } else {
      rejectedCount += 1
      h = hNew
    }
  }

  return {ts, ys, steps, acceptedCount, rejectedCount}
}
// result: runs adaptive RKF45 on [0, b] at the current tolerance ε.
//   steps, ts, ys — see rk45Solve
//   f — parsed right-hand side, reused for the reference trajectory in setup
//   acceptedCount, rejectedCount — step counters
//   finalValue — the computed y(b)
//   trueValue — reference y(b) via fixed-step RK4 with a very fine step count
//   actualError — |finalValue - trueValue|
result = {
  const math = window.math

  const f = VM.expressions.makeFunction2(math, committed.fText)
  const fallback = (t, y) =&gt; NaN

  if (!f) return {steps: [], ts: [], ys: [], f: fallback, acceptedCount: 0, rejectedCount: 0, finalValue: NaN, trueValue: NaN, actualError: NaN}

  const t0 = 0
  const y0 = committed.y0
  const b = committed.bEnd
  if (!Number.isFinite(y0) || !Number.isFinite(b) || b === t0) return {steps: [], ts: [], ys: [], f, acceptedCount: 0, rejectedCount: 0, finalValue: NaN, trueValue: NaN, actualError: NaN}

  const solved = rk45Solve(f, t0, y0, b, tolerance, maxSteps)

  if (solved.steps.length === 0) return {steps: [], ts: [], ys: [], f, acceptedCount: 0, rejectedCount: 0, finalValue: NaN, trueValue: NaN, actualError: NaN}

  const refSteps = 2000
  const trueValue = VM.numerical.rk4Solve(f, t0, y0, b, refSteps).ys[refSteps]
  const finalValue = solved.ys[solved.ys.length - 1]
  const actualError = Math.abs(finalValue - trueValue)

  return {steps: solved.steps, ts: solved.ts, ys: solved.ys, f, acceptedCount: solved.acceptedCount, rejectedCount: solved.rejectedCount, finalValue, trueValue, actualError}
}
// setup computes the data needed by the main chart: a fine reference
// trajectory for the smooth "true" solution curve, the adaptive trajectory,
// a per-point marker size (bigger where steps have shrunk, so refinement is
// visible directly on the solution curve), and the axis ranges.
setup = {
  if (result.steps.length === 0) {
    const empty = {lo: -3, hi: 3}
    return {ts: [], ys: [], pointSizes: [], refTs: [], refYs: [], tRange: empty, yRange: {lo: -1, hi: 1}}
  }

  const t0 = 0
  const y0 = committed.y0
  const b = committed.bEnd

  // A fine reference trajectory for the smooth "true" solution curve.
  const reference = VM.numerical.rk4Solve(result.f, t0, y0, b, 500)

  const tRange = VM.plotting.paddedRange([t0, b], {emptyRange: [-3, 3], relativePadding: 0.1, minPadding: 0.25})

  // Cap at 1e8 so a diverging solution doesn't blow up the axis range.
  const yValues = []
  for (const y of reference.ys) if (Number.isFinite(y) && Math.abs(y) &lt;= 1e8) yValues.push(y)
  for (const y of result.ys) if (Number.isFinite(y) && Math.abs(y) &lt;= 1e8) yValues.push(y)
  const yRange = VM.plotting.paddedRange(yValues, {emptyRange: [-1, 1], relativePadding: 0.25, minPadding: 0.5})

  // Marker size per accepted point, on a log scale of the step size that
  // produced it — smaller steps (more refinement) get bigger markers. t0
  // has no incoming step, so it reuses the first step's size.
  let minH = Infinity
  let maxH = 0
  for (const step of result.steps) {
    const h = Math.abs(step.h)
    if (h &lt; minH) minH = h
    if (h &gt; maxH) maxH = h
  }
  if (minH === maxH) {
    minH = minH * 0.5
    maxH = maxH * 2
  }
  const logMin = Math.log10(minH)
  const logMax = Math.log10(maxH)

  const sizeForH = h =&gt; {
    let ratio = (logMax - Math.log10(h)) / (logMax - logMin)
    if (!Number.isFinite(ratio)) ratio = 0.5
    return 5 + 9 * ratio
  }

  const pointSizes = [sizeForH(Math.abs(result.steps[0].h))]
  for (const step of result.steps) pointSizes.push(sizeForH(Math.abs(step.h)))

  return {ts: result.ts, ys: result.ys, pointSizes, refTs: reference.ts, refYs: reference.ys, tRange, yRange}
}
// mainPlot draws the fine reference solution curve and the adaptive RK45
// trajectory, with marker size showing where the step size shrunk to
// resolve fast dynamics.
//
// _plotDiv is kept in a closure so Plotly reuses the same DOM node across
// reactive updates — this preserves zoom and pan when the tolerance or max
// steps changes.
mainPlot = {
  const Plotly = window.Plotly
  let _plotDiv = null

  return (data) =&gt; {
    const traces = [
      // The fine reference solution curve
      {x: data.refTs, y: data.refYs, type: "scatter", mode: "lines", name: "Reference solution", showlegend: true, line: {color: "#2563eb", width: 3}}
    ]

    if (data.ts.length &gt; 0) {
      traces.push({
        x: data.ts, y: data.ys, type: "scatter", mode: "lines+markers", name: "Adaptive RK45", showlegend: true,
        line: {color: "#dc2626", width: 2}, marker: {color: "#dc2626", size: data.pointSizes, line: {color: "white", width: 1}}
      })
    }

    const layout = {
      margin: {l: 0, r: 0, t: 0, b: 0},
      xaxis: {title: "t", range: [data.tRange.lo, data.tRange.hi], zeroline: true},
      yaxis: {title: "y", range: [data.yRange.lo, data.yRange.hi], zeroline: true},
      legend: {orientation: "h", y: -0.08},
      hovermode: "closest",
      uirevision: "static",  // keeps zoom/pan state across reactive updates
      autosize: true
    }
    const config = {responsive: true, displaylogo: false}

    // First render: create the div. Later renders: update in place (preserves zoom).
    if (!_plotDiv) {
      _plotDiv = document.createElement("div")
      _plotDiv.className = "plotly-box-large"
      Plotly.newPlot(_plotDiv, traces, layout, config)
      // newPlot fires before the div is in the DOM, so Plotly measures 0 width.
      // A ResizeObserver catches the real size once it's inserted and laid out,
      // and keeps correcting it on any later layout/viewport change.
      new ResizeObserver(() =&gt; Plotly.Plots.resize(_plotDiv)).observe(_plotDiv)
    } else {
      Plotly.react(_plotDiv, traces, layout, config)
    }
    return _plotDiv
  }
}
RKF45 (Runge–Kutta–Fehlberg) adapts the step size \(h\) at every step, instead of the fixed \(h=b/n\) used in Explicit Methods. Six slope evaluations \(k_1,\dots,k_6\), each of the general Runge-Kutta form
\[
k_i = f\!\left(t_n + c_i h,\ y_n + h\sum_{j&lt;i} a_{ij}k_j\right),
\]
combine into two embedded estimates of \(y_{n+1}\) of different order, using two different weight sets \(b_i\), \(b_i^*\) on the same six \(k_i\):
\[
y_{n+1}^{(4)} = y_n + h\sum_{i=1}^{6} b_i k_i \qquad\text{(4th order)}, \qquad
y_{n+1}^{(5)} = y_n + h\sum_{i=1}^{6} b_i^{*} k_i \qquad\text{(5th order)}.
\]
If \(\left|y_{n+1}^{(5)} - y_{n+1}^{(4)}\right|\) exceeds a target tolerance \(\varepsilon\), the step is rejected and retried with a smaller \(h\); otherwise it’s accepted (using \(y_{n+1}^{(5)}\)) and \(h\) grows for the next step.

// VM is the shared utility library, loaded globally via _includes/head-scripts.html (js/**). This page uses VM.expressions.makeNumber, VM.expressions.makeRational.
