      // wrong jump. 1e-8 is well above that noise floor.
      if (Math.abs(dg) &lt; 1e-8) break
      const step = g / dg
      if (!Number.isFinite(step) || Math.abs(step) &gt; 1e6 * Math.max(1, Math.abs(z))) break
      z = z - step
