  if (highlightColor) {
    ctx.strokeStyle = highlightColor
    ctx.lineWidth = 3
    ctx.strokeRect(sensitivityLinePosition + 1.5, 1.5, specificityLinePosition - sensitivityLinePosition - 3, height - 3)
  }

